"""Tests for depcycle root package exports and version."""

from __future__ import annotations

import depcycle
from depcycle import (
    ASTParser,
    AnalysisConfig,
    DepCycleCLI,
    DotWriter,
    Graph,
    HtmlWriter,
    IOutputWriter,
    JsonWriter,
    Node,
    NodeType,
    PackageMetadataReader,
    Workspace,
)


def test_package_exports() -> None:
    assert hasattr(depcycle, "__version__")
    assert isinstance(depcycle.__version__, str)
    assert ASTParser is not None
    assert AnalysisConfig is not None
    assert DepCycleCLI is not None
    assert DotWriter is not None
    assert Graph is not None
    assert HtmlWriter is not None
    assert IOutputWriter is not None
    assert JsonWriter is not None
    assert Node is not None
    assert NodeType is not None
    assert PackageMetadataReader is not None
    assert Workspace is not None
    assert len(depcycle.__all__) == 12


def test_package_version_not_found(monkeypatch) -> None:
    import importlib.metadata

    def raise_not_found(name):
        raise importlib.metadata.PackageNotFoundError()

    monkeypatch.setattr(importlib.metadata, "version", raise_not_found)
    import sys

    if "depcycle" in sys.modules:
        del sys.modules["depcycle"]

    import depcycle as dc

    assert dc.__version__ == "0.0.0"
